  "A quarter of the window is held back for the answer — a prompt that exactly fills the context leaves no room to reply.": "Một phần tư cửa sổ được giữ lại cho câu trả lời — một prompt lấp đầy đúng ngữ cảnh sẽ không còn chỗ để trả lời.",
