  "— it thinks about meaning, not just filler words.": "— nó suy nghĩ về ý nghĩa, không chỉ bỏ từ thừa.",
  "Text to rewrite": "Văn bản cần viết lại",
  "Paste AI-generated or stiff text — it comes back sounding like a person wrote it.": "Dán văn bản do AI tạo hoặc cứng nhắc — nó sẽ trở lại như do người thật viết.",
  "Your writing sample": "Mẫu văn của bạn",
  "(this is what makes it sound like you)": "(đây là thứ giúp nó nghe giống bạn)",
  "Paste a few paragraphs you wrote yourself — an email, a message, anything in your natural voice.": "Dán vài đoạn do chính bạn viết — một email, một tin nhắn, bất cứ gì bằng giọng văn tự nhiên của bạn.",
  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "Giữ nguyên chính xác ý và dữ kiện của bạn — chỉ thay đổi cách đọc. Mẫu văn không bắt buộc nhưng tạo khác biệt lớn nhất.",
  "Rewritten": "Đã viết lại",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "Dán văn bản cứng nhắc hoặc nghe như AI, thêm một mẫu văn của bạn, và nó sẽ trở lại bằng giọng của bạn — cùng ý, nhịp văn tự nhiên.",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "Trò chuyện qua Attune — nó đọc toàn bộ cuộc trò chuyện và làm sắc nét từng prompt tiếp theo.",
  "What do you want out of this whole conversation? (optional, but it makes every prompt better)": "Bạn muốn đạt được gì từ cả cuộc trò chuyện này? (không bắt buộc, nhưng giúp mọi prompt tốt hơn)",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "Mang cuộc trò chuyện từ {t} sang — dán toàn bộ hoặc chỉ câu trả lời cuối cùng:",
  "Paste here…": "Dán vào đây…",
