  "Optimize my prompt": "Tối ưu prompt của tôi",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "Vòng lặp: gõ ý định → nhận prompt tối ưu → gửi đi → mang câu trả lời về → prompt tiếp theo càng chính xác hơn. Trong ứng dụng điện thoại, menu chia sẻ thay thế hoàn toàn việc sao chép-dán.",
