  "Run the AI on your own hardware. Nothing leaves the device, nothing costs per use.": "Chạy AI trên phần cứng của chính bạn. Không có gì rời khỏi thiết bị, không tốn phí mỗi lần dùng.",
  "Runs smoothly on a 12 GB phone: expert answers, and the best at reading documents and photos.": "Chạy mượt trên điện thoại 12 GB: câu trả lời chuyên gia, và đọc tài liệu, ảnh tốt nhất.",
