  "Too heavy for a phone — it can close the app. Core or Blaze run smoothly here; this one is in the desktop app.": "Quá nặng cho điện thoại — có thể làm ứng dụng bị đóng. Core hoặc Blaze chạy mượt ở đây; mô hình này có trong ứng dụng cho máy tính.",
