  "This phone can't write that photo type — try JPG or PNG.": "Điện thoại này không lưu được loại ảnh đó — hãy thử JPG hoặc PNG.",
  "This photo can't be opened here (HEIC photos: convert them to PDF instead).": "Không mở được ảnh này ở đây (ảnh HEIC: hãy chuyển sang PDF thay vào đó).",
  "No text was found in that file.": "Không tìm thấy chữ nào trong tệp đó.",
  "This PDF has no clear table, so each line became a row — check the columns.": "PDF này không có bảng rõ ràng, nên mỗi dòng thành một hàng — hãy kiểm tra các cột.",
  "Type the pages to keep, like 1-3, 5": "Nhập các trang cần giữ, ví dụ 1-3, 5",
