  "PDF files are converted by the Android app — open Attune on your phone.": "Tệp PDF được chuyển đổi trong ứng dụng Android — hãy mở Attune trên điện thoại.",
  "Free includes 5 conversions a day — Pro is unlimited": "Bản miễn phí gồm 5 lượt chuyển đổi mỗi ngày — Pro không giới hạn",
