  "This PDF is locked with a password — open it, save a copy without the password, and try again.": "PDF này bị khóa bằng mật khẩu — hãy mở nó, lưu một bản không có mật khẩu rồi thử lại.",
  "That file isn't a Word / Excel file (not a zip).": "Tệp đó không phải tệp Word / Excel (không phải tệp zip).",
