  "Earlier X-rays": "Các lần soi trước",
  "That doesn't look like an exported WhatsApp chat. In WhatsApp: open the chat → ⋮ → More → Export chat → Without media → Attune.": "Có vẻ đây không phải đoạn trò chuyện WhatsApp đã xuất. Trong WhatsApp: mở cuộc trò chuyện → ⋮ → Thêm → Xuất đoạn chat → Không kèm tệp phương tiện → Attune.",
  "Chat with {p}": "Trò chuyện với {p}",
