  "e.g. the taxi driver won't turn the meter on, what do I say? / is this price fair for a carpet? / can I drink the tap water?": "ví dụ: tài xế taxi không chịu bật đồng hồ, tôi nói gì? / giá này cho một tấm thảm có hợp lý không? / uống nước máy được không?",
  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "Nó biết mọi thứ thực sự vận hành ở đây thế nào — giá hợp lý, kiểu chặt chém phổ biến, điều gì bị coi là bất lịch sự. Nó sẽ cho bạn biết khi có thứ cần dữ liệu trực tuyến mà ngoại tuyến không có.",
