  "This model is large for this phone. It works, but answers come slowly and the phone gets warm. For quick, smooth answers use Qwen 3.5 4B — same Arabic, reads photos, about 3× faster.": "Mô hình này lớn so với điện thoại này. Vẫn chạy được, nhưng câu trả lời chậm và máy nóng lên. Để có câu trả lời nhanh, mượt hãy dùng Qwen 3.5 4B — cùng khả năng tiếng Ả Rập, đọc được ảnh, nhanh hơn khoảng 3 lần.",
  "GB ·": "GB ·",
