  "If the connection drops, it carries on from where it stopped next time.": "Nếu mất kết nối, lần sau nó sẽ tiếp tục từ chỗ đã dừng.",
  "Installed models": "Mô hình đã cài",
  "None yet — install the recommended one below, or add any model.": "Chưa có — hãy cài mô hình được đề xuất bên dưới, hoặc thêm một mô hình bất kỳ.",
  "In use": "Đang dùng",
  "Use": "Dùng",
  "Fingerprint": "Dấu vân tay",
