  "Tap again": "Chạm lần nữa",
  "Delete": "Xóa",
  "Installed weights never update on their own, so a prompt that works today works the same way in a year. The fingerprint proves exactly which file is answering.": "Trọng số đã cài không bao giờ tự cập nhật, nên một prompt chạy tốt hôm nay sẽ chạy y như vậy một năm sau. Dấu vân tay chứng minh chính xác tệp nào đang trả lời.",
  "Add any model": "Thêm một mô hình bất kỳ",
  "unsloth/Qwen3.5-9B-GGUF:Q4_K_M   or   https://…/model.gguf": "unsloth/Qwen3.5-9B-GGUF:Q4_K_M   hoặc   https://…/model.gguf",
  "Any GGUF on Hugging Face as": "Bất kỳ tệp GGUF nào trên Hugging Face dưới dạng",
  ", or a direct https link. Specialist and fine-tuned models install the same way — the photo reader is fetched too when the repo has one.": ", hoặc một liên kết https trực tiếp. Các mô hình chuyên biệt và tinh chỉnh cài theo cách tương tự — bộ đọc ảnh cũng được tải nếu kho có sẵn.",
  "How it answers": "Cách nó trả lời",
  "e.g. I run a small shop in Egypt. Answer in Egyptian Arabic unless I write in English. Give prices in EGP.": "ví dụ: Tôi có một cửa hàng nhỏ ở Ai Cập. Hãy trả lời bằng tiếng Ả Rập Ai Cập trừ khi tôi viết bằng tiếng Anh. Ghi giá bằng EGP.",
  "Saved when you tap outside the box. Stays on this phone.": "Được lưu khi bạn chạm ra ngoài khung. Chỉ ở lại trên điện thoại này.",
  "Web lookup": "Tra cứu web",
  "Only the question you look up and the pages opened leave the phone — never your conversation, files or memory.": "Chỉ câu hỏi bạn tra và các trang được mở mới rời khỏi điện thoại — không bao giờ là cuộc trò chuyện, tệp hay bộ nhớ của bạn.",
  "Hide network log": "Ẩn nhật ký mạng",
  "made ·": "đã kết nối ·",
  "blocked · this session": "bị chặn · phiên này",
  "Nothing has left the phone.": "Chưa có gì rời khỏi điện thoại.",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \"nothing leaves this phone\".": "Bản thân mô hình không bao giờ dùng mạng. Nhật ký liệt kê mọi kết nối ứng dụng đã thực hiện hoặc từ chối, chỉ gồm máy chủ và lý do — bằng chứng cho việc “không có gì rời khỏi điện thoại này”.",
  "Load a model to start": "Hãy tải một mô hình để bắt đầu",
  "Using the figure you gave.": "Dùng con số bạn đã nhập.",
  "Running now": "Đang chạy",
  "Smaller ·": "Nhỏ hơn ·",
  "may fit — try it": "có thể vừa — thử xem",
  "draft · ~2× faster, lossless": "bản nháp · nhanh hơn ~2 lần, không giảm chất lượng",
  "Parity: unverified until this tier passes its eval set — ✓ appears only after it does.": "Tương đương: chưa được xác minh cho đến khi cấp này vượt qua bộ đánh giá — dấu ✓ chỉ hiện sau đó.",
  "Needs": "Cần",
