  "GB (mmap)": "GB (mmap)",
  "KV": "KV",
  "% cache": "% bộ đệm",
  "GB total": "GB tổng cộng",
  "INT4 KV cache + sliding-window eviction, so long conversations don't grow unbounded.": "Bộ đệm KV INT4 + loại bỏ theo cửa sổ trượt, để các cuộc trò chuyện dài không phình ra vô hạn.",
  "Storage:": "Lưu trữ:",
  "Compute": "Tính toán",
  "Prefill runs where compute is fastest, decode where bandwidth is. Using both raises usable bandwidth ~43 → 59 GB/s.": "Prefill chạy ở nơi tính toán nhanh nhất, decode chạy ở nơi băng thông cao nhất. Dùng cả hai nâng băng thông khả dụng từ ~43 lên 59 GB/s.",
  "Task adapters": "Bộ điều hợp tác vụ",
  "Small fine-tunes for each job — this is what makes a phone-sized model punch above its weight. Loaded over the base model, a few MB each.": "Các bản tinh chỉnh nhỏ cho từng việc — đây là điều giúp mô hình cỡ điện thoại vượt xa tầm vóc của nó. Nạp chồng lên mô hình gốc, mỗi bộ chỉ vài MB.",
