  "Your real names for your real things. Every document then uses them correctly — no invented equipment names, no wrong site spellings. Stays on your devices.": "Tên thật cho những thứ thật của bạn. Mọi tài liệu sẽ dùng chúng đúng cách — không có tên thiết bị bịa ra, không sai chính tả địa điểm. Chỉ ở lại trên thiết bị của bạn.",
