  "Turns logged downtime into a figure you can put in front of management.": "Biến thời gian ngừng hoạt động đã ghi thành con số bạn có thể đưa cho ban quản lý.",
  "Reporting rules": "Quy tắc báo cáo",
  "e.g. every incident must state whether work was stopped; always record permit number": "ví dụ: mỗi sự cố phải nêu rõ công việc có bị dừng không; luôn ghi số giấy phép",
  "This is added to every field document — and it's also what your own adapter trains on, so the model learns your operation, not a generic one.": "Nội dung này được thêm vào mọi tài liệu hiện trường — và cũng là thứ bộ điều hợp riêng của bạn học, để mô hình hiểu hoạt động của bạn chứ không phải một hoạt động chung chung.",
