  "Merge": "Gộp",
  "Keep everything on this phone and add the backup's chats, memory, reminders and cycle days. The Money ledger is only taken from the backup if this phone has none.": "Giữ mọi thứ trên điện thoại này và thêm các cuộc trò chuyện, bộ nhớ, lời nhắc và ngày chu kỳ từ bản sao lưu. Sổ Tiền chỉ lấy từ bản sao lưu nếu điện thoại này chưa có.",
  "This phone's {c} chats and {l} ledger entries will be replaced by the backup's. You can undo this once, right after.": "{c} cuộc trò chuyện và {l} khoản trong sổ của điện thoại này sẽ bị thay bằng của bản sao lưu. Bạn có thể hoàn tác một lần ngay sau đó.",
