  "No model is loaded. Open Engine in Attune and load one.": "Chưa nạp mô hình nào. Hãy mở Động cơ trong Attune và nạp một mô hình.",
  "Attune does not answer that kind of request.": "Attune không trả lời loại yêu cầu đó.",
  "Suggested. The free tier stops when it runs out instead of charging you.": "Được đề xuất. Gói miễn phí sẽ dừng khi hết hạn mức thay vì tính phí bạn.",
  "Needs a card on file. An independent index — good in English, unproven in Arabic.": "Cần thẻ đã lưu. Một chỉ mục độc lập — tốt với tiếng Anh, chưa được kiểm chứng với tiếng Ả Rập.",
  "Returns Google's own results, so the best Arabic quality of the three.": "Trả về kết quả của chính Google, nên có chất lượng tiếng Ả Rập tốt nhất trong ba lựa chọn.",
  "as a table": "dạng bảng",
  "step by step": "từng bước",
  "with examples": "kèm ví dụ",
  "for a beginner": "cho người mới bắt đầu",
  "corrected by you": "do bạn sửa",
  "Free": "Miễn phí",
  "$99.99/yr · $299.99 once, forever": "$99.99/năm · $299.99 một lần, trọn đời",
  "On-device": "Trên thiết bị",
  "The only mode. Nothing leaves this device.": "Chế độ duy nhất. Không có gì rời khỏi thiết bị này.",
  "Write a polite reply to this message: ": "Viết một câu trả lời lịch sự cho tin nhắn này: ",
  "Translate into English: ": "Dịch sang tiếng Anh: ",
  "Summarise this in 3 bullets: ": "Tóm tắt trong 3 gạch đầu dòng: ",
  "What should I check on a used car before I buy it?": "Tôi nên kiểm tra gì ở xe ô tô cũ trước khi mua?",
  "My period started this morning, medium flow": "Kỳ kinh của tôi bắt đầu sáng nay, lượng máu vừa",
  "Add it to your ledger in Money? You'll pick the account and confirm there.": "Thêm vào sổ của bạn trong Tiền? Bạn sẽ chọn tài khoản và xác nhận ở đó.",
  "Spotting": "Ra ít (spotting)",
  "Light": "Ít",
  "Medium": "Vừa",
  "Heavy": "Nhiều",
  "item": "mục",
  "items": "mục",
  "15 questions a day": "15 câu hỏi mỗi ngày",
  "3 templates · 5 history items": "3 mẫu · 5 mục lịch sử",
  "35B of knowledge, 3B doing the work on each token — near-frontier answers at a speed a laptop can sustain. A mixture-of-experts model keeps every expert in memory even though few run per token, so this needs the RAM of a 35B and the compute of a 3B.": "Kiến thức của 35B, chỉ 3B thực hiện công việc cho mỗi token — câu trả lời gần đạt đỉnh cao với tốc độ laptop có thể duy trì. Mô hình hỗn hợp chuyên gia giữ mọi chuyên gia trong bộ nhớ dù mỗi token chỉ chạy vài chuyên gia, nên cần RAM của mô hình 35B và sức tính của mô hình 3B.",
  "A bigger length budget for reports, plans and analysis.": "Ngân sách độ dài lớn hơn cho báo cáo, kế hoạch và phân tích.",
  "Ask it as much as you like — no daily limit": "Hỏi bao nhiêu tùy thích — không giới hạn hằng ngày",
  "Your phone reports {n} GB of memory": "Điện thoại của bạn báo bộ nhớ {n} GB",
  "Your computer reports {n} GB of memory": "Máy tính của bạn báo bộ nhớ {n} GB",
  "which is comfortable for everyday use": "mức này thoải mái cho việc dùng hằng ngày",
  "which is enough, with shorter conversations": "mức này đủ dùng, với các cuộc trò chuyện ngắn hơn",
  ", ": ", ",
  "Documents, fleet records, copilot, every domain pack": "Tài liệu, hồ sơ đội xe, trợ lý, mọi gói lĩnh vực",
  "Small enough to download on mobile data if you need to.": "Đủ nhỏ để tải bằng dữ liệu di động khi cần.",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "Đây là mô hình lớn đối với điện thoại. Nó vẫn chạy, nhưng sẽ chậm đi rõ rệt khi máy nóng lên — hãy giữ câu trả lời ngắn, hoặc chọn mô hình nhỏ hơn.",
  "Every tool, and all 31 country packs": "Mọi công cụ và toàn bộ 31 gói quốc gia",
  "Finds what you promised people, from your own words": "Tìm những gì bạn đã hứa với mọi người, từ chính lời của bạn",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "Tính ngẫu nhiên cố định, nên một quy trình cho ra kết quả giống hệt nhau mỗi lần chạy.",
  "Free web search: DuckDuckGo, Bing and Mojeek at once, then the top pages are read in full, so answers come from real passages.": "Tìm web miễn phí: DuckDuckGo, Bing và Mojeek cùng lúc, rồi các trang hàng đầu được đọc đầy đủ, nên câu trả lời đến từ các đoạn văn thật.",
  "Free · no key": "Miễn phí · không cần khóa",
  "Installing… {p}%": "Đang cài đặt… {p}%",
  "It remembers everything and can search it": "Nó nhớ mọi thứ và tìm lại được",
  "Learns your vocabulary and writes the way you do": "Học vốn từ của bạn và viết theo cách của bạn",
  "No account, no sign-in, nothing uploaded": "Không tài khoản, không đăng nhập, không tải gì lên",
  "Running": "Đang chạy",
  "Loading the model…": "Đang nạp mô hình…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "Không thứ gì trong ứng dụng có thể truy cập internet — không tra cứu web, không bản đồ, không tải xuống. Mô hình và mọi thứ trên điện thoại vẫn hoạt động.",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "Mô hình suy luận trước với mọi câu hỏi. Rõ ràng tốt hơn với bài khó, nhưng trên điện thoại câu trả lời bắt đầu chậm hơn 30–90 giây. Khi tắt: chạm “Suy nghĩ” chỉ với những câu cần.",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "Cùng mô hình ở bên dưới, nhưng có bộ nhớ để chứa cả một cuốn sách ngữ cảnh cùng lúc. Trên máy 48 GB, RAM dư dùng cho ngữ cảnh tốt hơn là cho độ chính xác — bạn có thể đưa cả một hợp đồng hay một năm ghi chú và nó giữ tất cả trong tầm nhìn.",
  "The whole assistant, on your device": "Toàn bộ trợ lý, ngay trên thiết bị của bạn",
  "Works entirely offline. No account, ever.": "Hoạt động hoàn toàn ngoại tuyến. Không bao giờ cần tài khoản.",
