  "Notifications are off for Attune — tap to allow them, or reminders can't appear.": "Thông báo của Attune đang tắt — chạm để cho phép, nếu không nhắc nhở sẽ không hiện.",
  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "Nhắc nhở có thể trễ tới 10 phút. Chạm để cho phép “Báo thức và lời nhắc” cho Attune để chúng reo đúng phút.",
  "In the browser reminders are only listed — the Android app rings them.": "Trong trình duyệt, nhắc nhở chỉ được liệt kê — ứng dụng Android mới làm chúng reo.",
  "from a promise": "từ một lời hứa",
