  "That time has already passed — pick a later one.": "Thời điểm đó đã qua — hãy chọn thời điểm muộn hơn.",
  "That is more than a year away — check the date.": "Hơn một năm nữa — hãy kiểm tra lại ngày.",
  "Who should it go to?": "Gửi cho ai?",
