  "Could not open it": "Không thể mở",
  "No app on this phone can do that.": "Không có ứng dụng nào trên điện thoại này làm được việc đó.",
  "WhatsApp isn't installed — opened the share sheet instead.": "WhatsApp chưa được cài — đã mở bảng chia sẻ thay thế.",
