  "Facts the AI should know (prices, rules, terms — optional)": "Những dữ kiện AI cần biết (giá, quy tắc, điều khoản — không bắt buộc)",
  "Separate topics with an empty line. Only the paragraphs that fit the question are used, so this can be long.": "Tách các chủ đề bằng một dòng trống. Chỉ những đoạn phù hợp với câu hỏi mới được dùng, nên phần này có thể dài.",
  "Facts": "Dữ kiện",
  "It also runs this small program on your phone (offline, in a locked box — no internet, no files, no access to the app)": "Nó cũng chạy chương trình nhỏ này trên điện thoại của bạn (ngoại tuyến, trong một hộp khóa kín — không internet, không tệp, không truy cập ứng dụng)",
  "Edit or improve my CV": "Sửa hoặc cải thiện CV của tôi",
  "Say what to add or change («add my job at Dar Al Fouad Hospital as a nurse, 2019–2022», «change my phone to …»), or leave it empty and just make it more professional. You see the result before it is kept.": "Hãy nói cần thêm hoặc đổi gì («thêm công việc y tá tại Bệnh viện Dar Al Fouad, 2019–2022», «đổi số điện thoại của tôi thành …»), hoặc để trống và chỉ làm cho chuyên nghiệp hơn. Bạn sẽ thấy kết quả trước khi nó được giữ lại.",
  "What should be added or changed? (optional)": "Cần thêm hoặc đổi gì? (không bắt buộc)",
