  "Current photo quality in 4 steps: people, places, products and text in pictures. Also edits a photo you give it (“make it night”, “remove the car”).": "Chất lượng ảnh hiện đại trong 4 bước: người, địa điểm, sản phẩm và chữ trong ảnh. Cũng chỉnh sửa ảnh bạn đưa (“đổi thành ban đêm”, “xóa chiếc xe”).",
  "Describe the picture, in Arabic or English — e.g. “a felucca on the Nile at sunset”": "Mô tả bức ảnh, bằng tiếng Ả Rập hoặc tiếng Anh — ví dụ “một chiếc thuyền felucca trên sông Nile lúc hoàng hôn”",
  "Developing the picture…": "Đang tráng ảnh…",
  "Download it on Wi-Fi. After that, pictures are made with no internet at all.": "Hãy tải qua Wi-Fi. Sau đó ảnh được tạo mà hoàn toàn không cần internet.",
  "Draw it": "Vẽ",
