  "Draw on the graphics chip (faster; switches itself off if the driver fails)": "Vẽ trên chip đồ họa (nhanh hơn; tự tắt nếu trình điều khiển lỗi)",
  "Drawing on the GPU failed, so Attune switched Studio to the CPU. ": "Vẽ trên GPU thất bại, nên Attune đã chuyển Studio sang CPU. ",
  "Drawing — step {n} of {t}": "Đang vẽ — bước {n}/{t}",
  "Each picture is made by a separate engine process: when it finishes, all its memory goes back to the phone. Nothing is uploaded.": "Mỗi ảnh được tạo bởi một tiến trình động cơ riêng: khi xong, toàn bộ bộ nhớ của nó trả lại cho điện thoại. Không có gì được tải lên.",
