  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "Phiên bản Attune này chưa có động cơ ảnh trên chip đồ họa, nên ảnh được vẽ bằng CPU (chậm hơn). Bản cập nhật sẽ bổ sung.",
  "The picture engine stopped responding while loading the model, so it was stopped. Engine → Engine log shows its last lines — send them to support.": "Động cơ ảnh ngừng phản hồi khi nạp mô hình nên đã bị dừng. Động cơ → Nhật ký động cơ hiển thị các dòng cuối — hãy gửi cho bộ phận hỗ trợ.",
  "This phone's GPU driver did not answer, so pictures are drawn on the CPU (slower).": "Trình điều khiển GPU của điện thoại không phản hồi, nên ảnh được vẽ bằng CPU (chậm hơn).",
