  "The best pictures this phone can make: the 8-bit build of FLUX.2 klein — finer detail, cleaner faces, hands and text. Also edits your photos by instruction.": "Những bức ảnh đẹp nhất điện thoại này có thể tạo: bản 8-bit của FLUX.2 klein — chi tiết mịn hơn, khuôn mặt, bàn tay và chữ sạch hơn. Cũng chỉnh sửa ảnh của bạn theo chỉ dẫn.",
  "That file is too large (15 MB at most)": "Tệp đó quá lớn (tối đa 15 MB)",
