  "Wrong? Teach the right answer": "Sai? Hãy dạy đáp án đúng",
  "What should it have said? Chat will answer this way next time you ask something like it.": "Lẽ ra nó nên nói gì? Lần sau bạn hỏi điều tương tự, Chat sẽ trả lời theo cách này.",
  "The right answer": "Câu trả lời đúng",
  "Why (optional) — e.g. “the marble falls out when the glass is turned over”": "Vì sao (không bắt buộc) — ví dụ “viên bi rơi ra khi lật úp cốc”",
  "Learned — Chat will use this on similar questions": "Đã học — Chat sẽ dùng điều này cho các câu hỏi tương tự",
  "That is the same as the answer — nothing to learn": "Giống hệt câu trả lời — không có gì để học",
