  "Could not check it: {e}": "Không kiểm tra được: {e}",
  "Could not check it (no answer from the model).": "Không kiểm tra được (mô hình không trả lời).",
  "The phone's storage for Business is full — export a table to CSV and delete old records.": "Bộ nhớ của Kinh doanh trên điện thoại đã đầy — hãy xuất một bảng ra CSV và xóa các bản ghi cũ.",
  "Created — {n} tables": "Đã tạo — {n} bảng",
  "Deleted": "Đã xóa",
  "Your own ERP: customers, stock, jobs, invoices — whatever your business tracks. Change any table or column later, like Microsoft Access.": "ERP của riêng bạn: khách hàng, kho, công việc, hóa đơn — bất cứ thứ gì doanh nghiệp bạn theo dõi. Đổi bất kỳ bảng hay cột nào sau này, như Microsoft Access.",
  "{n} tables": "{n} bảng",
  "Active": "Đang dùng",
  "Trial": "Dùng thử",
  "The model didn't produce a usable design. Try again, describe it differently, or start from a template.": "Mô hình không tạo được thiết kế dùng được. Hãy thử lại, mô tả khác đi, hoặc bắt đầu từ một mẫu.",
