  "e.g. We rent mobile cranes (20–500 t) with operators in Egypt. We track customers, jobs per site, daily rates, invoices and payments, maintenance and crew licences.": "ví dụ: Chúng tôi cho thuê cẩu di động (20–500 tấn) kèm người vận hành ở Ai Cập. Chúng tôi theo dõi khách hàng, công việc theo công trường, giá thuê theo ngày, hóa đơn và thanh toán, bảo trì và bằng lái của đội ngũ.",
  "Designing your system…": "Đang thiết kế hệ thống của bạn…",
  "Design it with AI": "Thiết kế bằng AI",
